import {t} from './locales.js';
import {iso,diamond} from './isometric.js';
const NS='http://www.w3.org/2000/svg';
/** @param {string} name @param {Record<string,string|number>} attrs @param {Element} parent */
function node(name,attrs,parent){const n=document.createElementNS(NS,name);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,String(v));parent.append(n);return n;}
/** @param {{x:number,y:number}[]} values */
const points=values=>values.map(p=>p.x+','+p.y).join(' ');
/** @param {number} x @param {number} y @param {number} w @param {number} h */
const corners=(x,y,w,h)=>[iso(x,y),iso(x+w,y),iso(x+w,y+h),iso(x,y+h)];
/** @param {{x:number,y:number}} p @param {number} h */
const up=(p,h)=>({x:p.x,y:p.y-h});
/** @param {Element} parent @param {number[]} edge */
function fence(parent,edge){const a=iso(edge[0],edge[1]),b=iso(edge[2],edge[3]),g=node('g',{'data-cow-fence':'','pointer-events':'none'},parent);for(const h of [12,25])node('path',{d:`M${a.x},${a.y-h} L${b.x},${b.y-h}`,stroke:'#b69b6b','stroke-width':3},g);for(let i=0;i<=5;i++){const x=a.x+(b.x-a.x)*i/5,y=a.y+(b.y-a.y)*i/5;node('path',{d:`M${x},${y+3} v-37`,stroke:'#bcaa7a','stroke-width':5,'stroke-linecap':'round'},g);}}
/** Cutaway shelter keeps the straw rest space visible. @param {Element} parent */
function barn(parent){const [a,b,c,d]=corners(1,.7,3.2,2.1),g=node('g',{'data-cow-barn':'','aria-label':t('cowBarnShelter')},parent);node('polygon',{points:points([a,b,c,d]),fill:'#ddca93',stroke:'#b6a26c','stroke-width':2},g);node('polygon',{points:points([a,b,up(b,55),up(a,55)]),fill:'#caa883',stroke:'#ab8862','stroke-width':2},g);node('polygon',{points:points([a,d,up(d,55),up(a,55)]),fill:'#dfc29a',stroke:'#ab8862','stroke-width':2},g);const roof=corners(.8,.5,3.6,1.1).map(p=>up(p,66)),ridge=corners(.8,.5,3.6,.05).map(p=>up(p,85));node('polygon',{points:points([roof[3],roof[2],ridge[1],ridge[0]]),fill:'#b77455',stroke:'#985d43','stroke-width':2},g);node('polygon',{points:points([roof[0],roof[1],ridge[1],ridge[0]]),fill:'#cb8b65'},g);for(const p of [b,c,d])node('path',{d:`M${p.x},${p.y} v-59`,stroke:'#b89b71','stroke-width':6},g);node('polygon',{points:points(corners(1.6,1.4,2,1)),fill:'#dbc17e','data-cow-rest':''},g);for(let i=0;i<8;i++){const p=iso(1.7+i%4*.5,1.7+Math.floor(i/4)*.5);node('path',{d:`M${p.x-8},${p.y} l13,-3 m-6,7 l10,-3`,stroke:'#bba464','stroke-width':2},g);}}
/** @param {Element} parent */
function stations(parent){
 for(const [id,x,y,key]of /** @type {const} */([['feed',1.4,4.8,'cowFeeder'],['water',5.8,2.5,'cowWaterTrough']])){const p=iso(x,y),g=node('g',{'data-cow-station':id,'aria-label':t(key)},parent),water=id==='water';node('path',{d:`M${p.x-34},${p.y-12} v21 q34,17 68,0 v-21 Z`,fill:water?'#9db6ac':'#b59c73',stroke:water?'#6c9188':'#8e7c5b','stroke-width':2},g);node('ellipse',{cx:p.x,cy:p.y-12,rx:34,ry:12,fill:water?'#d3dfd5':'#c6ad74',stroke:water?'#6c9188':'#8e7c5b','stroke-width':2},g);}
 const p=iso(5.2,5.3),stand=node('g',{'data-cow-station':'stand','aria-label':t('cowMilkingStand')},parent);node('polygon',{points:points(corners(4.7,4.7,1.4,1.3).map(p=>up(p,7))),fill:'#d8bd88',stroke:'#aa8e62','stroke-width':2},stand);for(const dx of [-24,24])node('path',{d:`M${p.x+dx},${p.y+5} v-47 h${dx<0?15:-15}`,stroke:'#909e8a','stroke-width':4,fill:'none'},stand);
 const can=iso(6.2,4.1),milk=node('g',{'data-cow-station':'can','aria-label':t('cowMilkCan')},parent);node('path',{d:`M${can.x-14},${can.y-34} l-5,10 v27 q19,11 38,0 v-27 l-5,-10 Z`,fill:'#cbd6d0',stroke:'#81978d','stroke-width':2},milk);node('ellipse',{cx:can.x,cy:can.y-34,rx:14,ry:5,fill:'#e2e8dd',stroke:'#81978d','stroke-width':2},milk);node('path',{d:`M${can.x-14},${can.y-27} q-20,-1 -10,18 M${can.x+14},${can.y-27} q20,-1 10,18`,fill:'none',stroke:'#81978d','stroke-width':3},milk);
 const sign=iso(5.6,.8),coop=node('g',{'data-cow-station':'coop','aria-label':t('cowCoop')},parent);node('path',{d:`M${sign.x},${sign.y+6} v-57`,stroke:'#ad9164','stroke-width':5},coop);node('rect',{x:sign.x-36,y:sign.y-56,width:72,height:30,rx:5,fill:'#f2e5bd',stroke:'#bca16b','stroke-width':2},coop);node('text',{x:sign.x,y:sign.y-37,'font-size':11,'text-anchor':'middle',fill:'#36553c'},coop).textContent=t('cowCoopSign');
 const clean=iso(.8,3.3),brush=node('g',{'data-cow-station':'clean','aria-label':t('cowCleanStation')},parent);node('path',{d:`M${clean.x},${clean.y} l20,-34`,stroke:'#b08c5c','stroke-width':4},brush);node('path',{d:`M${clean.x-13},${clean.y-8} l23,10 l-7,12 l-23,-10 Z`,fill:'#dbbc74',stroke:'#b49a66','stroke-width':2},brush);
}
/** Original SVG presentation: no resources, timers, grants or persistence. */
export function renderCowWorld(){const host=/** @type {HTMLElement} */(document.querySelector('#world'));host.replaceChildren();const svg=node('svg',{viewBox:'0 0 900 540',class:'farm-scene cow-scene',role:'img','aria-label':t('cowArea')},host);node('title',{},svg).textContent=t('cowArea');node('ellipse',{cx:450,cy:355,rx:337,ry:137,fill:'#91a779',opacity:'.23'},svg);const map=node('g',{id:'map-camera'},svg);node('polygon',{points:'98,236 450,412 802,236 802,263 450,439 98,263',fill:'#92a975'},map);for(let y=0;y<8;y++)for(let x=0;x<8;x++){const p=iso(x,y);node('polygon',{points:diamond(p.x,p.y),fill:(x+y)%4===0?'#d8dfb6':'#cbd7a7',stroke:'#b8c792','stroke-width':'.5','data-cow-tile':y*8+x},map);}const edges=[[.3,.3,6.8,.3],[.3,.3,.3,6.8],[6.8,.3,6.8,6.8],[.3,6.8,6.8,6.8]];for(const edge of edges.slice(0,2))fence(map,edge);barn(map);stations(map);for(const edge of edges.slice(2))fence(map,edge);}
